def fib_slow(n):
    if n <= 1: return n
    return fib_slow(n - 1) + fib_slow(n - 2)

from functools import lru_cache

def fib_memo(n):
    @lru_cache(None)
    def solve(k):
        if k <= 1: return k
        return solve(k - 1) + solve(k - 2)
    return solve(n)

def fib_rolling(n):
    previous, current = 0, 1
    for _ in range(n):
        previous, current = current, previous + current
    return previous

def min_cost(cost):
    dp = [0] * (len(cost) + 1)
    for i in range(1, len(dp)):
        dp[i] = dp[i - 1] + cost[i - 1]
    return dp[-1]

def climbing_stairs(n):
    if n < 0: return 0
    previous, current = 1, 1
    for _ in range(2, n + 1):
        previous, current = current, previous + current
    return current

def house_robber(values):
    two_back = one_back = 0
    for value in values:
        two_back, one_back = one_back, max(one_back, two_back + value)
    return one_back

def maximum_subarray(numbers):
    if not numbers: raise ValueError("不可為空")
    ending_here = best = numbers[0]
    for value in numbers[1:]:
        ending_here = max(value, ending_here + value)
        best = max(best, ending_here)
    return best

def coin_change(coins, amount):
    dp = [float('inf')] * (amount + 1); dp[0] = 0
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value: dp[value] = min(dp[value], dp[value-coin] + 1)
    return -1 if dp[amount] == float('inf') else dp[amount]

def word_break(text, words):
    words = set(words); dp = [False] * (len(text)+1); dp[0] = True
    for end in range(1, len(text)+1):
        dp[end] = any(dp[start] and text[start:end] in words for start in range(end))
    return dp[-1]

def unique_paths(rows, cols):
    dp = [[1] * cols for _ in range(rows)]
    for r in range(1, rows):
        for c in range(1, cols): dp[r][c] = dp[r-1][c] + dp[r][c-1]
    return dp[-1][-1]

def minimum_path_sum(grid):
    rows, cols = len(grid), len(grid[0]); dp = [float('inf')] * cols
    for r in range(rows):
        for c in range(cols):
            if r == c == 0: dp[c] = grid[r][c]
            else: dp[c] = min(dp[c], dp[c-1] if c else float('inf')) + grid[r][c]
    return dp[-1]

def lcs_length(a, b):
    dp = [[0]*(len(b)+1) for _ in range(len(a)+1)]
    for i in range(1, len(a)+1):
        for j in range(1, len(b)+1):
            dp[i][j] = dp[i-1][j-1]+1 if a[i-1]==b[j-1] else max(dp[i-1][j], dp[i][j-1])
    return dp[-1][-1]

def edit_distance(a, b):
    dp = [[0]*(len(b)+1) for _ in range(len(a)+1)]
    for i in range(len(a)+1): dp[i][0] = i
    for j in range(len(b)+1): dp[0][j] = j
    for i in range(1, len(a)+1):
        for j in range(1, len(b)+1):
            dp[i][j] = dp[i-1][j-1] if a[i-1]==b[j-1] else 1+min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[-1][-1]

def knapsack_2d(weights, values, capacity):
    n=len(weights); dp=[[0]*(capacity+1) for _ in range(n+1)]
    for i in range(1,n+1):
        for c in range(capacity+1):
            dp[i][c]=dp[i-1][c]
            if weights[i-1]<=c: dp[i][c]=max(dp[i][c],dp[i-1][c-weights[i-1]]+values[i-1])
    return dp[n][capacity]

def knapsack(weights, values, capacity):
    dp=[0]*(capacity+1)
    for weight,value in zip(weights,values):
        for c in range(capacity,weight-1,-1):
            dp[c]=max(dp[c],dp[c-weight]+value)
    return dp[capacity]

def complete_knapsack(weights, values, capacity):
    dp=[0]*(capacity+1)
    for weight,value in zip(weights,values):
        for c in range(weight,capacity+1): dp[c]=max(dp[c],dp[c-weight]+value)
    return dp[capacity]

def subset_sum(numbers, target):
    dp=[False]*(target+1); dp[0]=True
    for value in numbers:
        for total in range(target,value-1,-1): dp[total] |= dp[total-value]
    return dp[target]

def can_partition(numbers):
    total=sum(numbers)
    return False if total%2 else subset_sum(numbers,total//2)

def lis_quadratic(numbers):
    if not numbers: return 0
    dp=[1]*len(numbers)
    for i in range(len(numbers)):
        for j in range(i):
            if numbers[j]<numbers[i]: dp[i]=max(dp[i],dp[j]+1)
    return max(dp)

from bisect import bisect_left

def lis_length(numbers):
    tails=[]
    for value in numbers:
        index=bisect_left(tails,value)
        if index==len(tails): tails.append(value)
        else: tails[index]=value
    return len(tails)

def longest_palindrome_subsequence(text):
    n=len(text); dp=[[0]*n for _ in range(n)]
    for i in range(n): dp[i][i]=1
    for length in range(2,n+1):
        for left in range(n-length+1):
            right=left+length-1
            dp[left][right]=dp[left+1][right-1]+2 if text[left]==text[right] else max(dp[left+1][right],dp[left][right-1])
    return 0 if n==0 else dp[0][n-1]
